// Which app goal each focus area points to.
const AREA_GOAL = { belly:'core', glutes:'gluteos', legs:'gluteos', arms:'postura', back:'postura', whole:'corpo' };

// The goals to use in the app: main goal first, then the focus areas, then back care if she has back or neck pain.
function quizGoals(a) {
  const out = [];
  const add = (g) => { if (g && GOALS.some((x) => x.id === g) && out.indexOf(g) === -1) out.push(g); };
  add(a.goal);
  (a.areas || []).forEach((x) => add(AREA_GOAL[x]));
  if ((a.pains || []).some((p) => p === 'back' || p === 'neck')) add('postura');
  if (!out.length) add('corpo');
  return out.slice(0, 3);
}

// Her first week: one class per practice day, picked like the app's own recommendation
// (closest to her minutes and level), rotating through her goals.
function firstWeek(a) {
  const level = Math.min(3, Math.max(1, Number(a.level) || 1));
  const time = Number(a.time) || 15;
  const days = Math.min(5, Math.max(2, Number(a.days) || 3));
  const score = (id) => Math.abs(CLASSES[id].min - time) + 12 * Math.abs(CLASSES[id].level - level);
  const pools = quizGoals(a).map((g) => GOALS.find((x) => x.id === g).cls.filter((id) => CLASSES[id] && CLASSES[id].level <= level + 0));
  const picked = [];
  if (level === 1) picked.push('fundamentos');
  if ((a.pains || []).some((p) => p === 'back' || p === 'neck')) picked.push(time <= 10 ? 'postura10' : 'costas');
  let i = 0, guard = 0;
  while (picked.length < days && guard++ < 50) {
    const pool = pools[i++ % pools.length].filter((id) => picked.indexOf(id) === -1).sort((x, y) => score(x) - score(y));
    if (pool.length) picked.push(pool[0]);
    else if (guard > pools.length * 3) {
      const rest = Object.keys(CLASSES).filter((id) => !CLASSES[id].fixed && ['tpm', 'gestacao'].indexOf(id) === -1 && CLASSES[id].level <= level && picked.indexOf(id) === -1).sort((x, y) => (CLASSES[x].mod === 'corpo' ? 0 : 100) + score(x) - (CLASSES[y].mod === 'corpo' ? 0 : 100) - score(y));
      if (!rest.length) break;
      picked.push(rest[0]);
    }
  }
  return picked.slice(0, days).map((id) => {
    const C = CLASSES[id];
    return { id, min: C.min, level: C.level, hero: C.hero, en: C.en.title, pt: C.title };
  });
}

